<?php
require_once __DIR__.'/includes/bootstrap.php';$slug=trim($_GET['slug']??'');$preview=!empty($_GET['preview'])&&!empty($_SESSION['admin_id']);$sql='SELECT p.*,CASE WHEN p.cover_image_public=1 AND p.cover_image_approved=1 THEN p.cover_image ELSE NULL END AS public_cover_image,CASE WHEN p.hero_image_public=1 AND p.hero_image_approved=1 THEN p.hero_image ELSE NULL END AS public_hero_image,c.name category_name,s.seo_title,s.meta_description,s.focus_keyword,s.canonical_url,s.og_title,s.og_description,s.og_image,s.schema_type FROM projects p JOIN project_categories c ON c.id=p.category_id LEFT JOIN project_seo s ON s.project_id=p.id WHERE p.slug=?'.($preview?'':' AND p.status=\'published\'');$q=db()->prepare($sql);$q->execute([$slug]);$p=$q->fetch();if(!$p){http_response_code(404);exit('Project not found');}
if(!$preview){$visitor=hash('sha256',session_id().'|'.($_SERVER['HTTP_USER_AGENT']??''));$dedupe=(int)setting('views_dedupe_minutes','30');$key='view_'.$p['id'];$last=(int)($_SESSION[$key]??0);if(time()-$last >= max(1,$dedupe)*60){db()->prepare('INSERT INTO page_views(project_id,visitor_hash) VALUES(?,?)')->execute([$p['id'],$visitor]);$_SESSION[$key]=time();}}
$vf=db()->prepare("SELECT f.label,f.unit,f.input_type,v.value_json FROM project_field_values v JOIN category_fields f ON f.id=v.field_id WHERE v.project_id=? AND v.visibility IN ('public','optional') AND f.is_active=1 ORDER BY f.sort_order");$vf->execute([$p['id']]);$specs=$vf->fetchAll();$images=db()->prepare('SELECT * FROM project_images WHERE project_id=? AND is_public=1 AND is_approved=1 ORDER BY is_cover DESC,sort_order,id');$images->execute([$p['id']]);$images=$images->fetchAll();$contents=db()->prepare('SELECT heading,body FROM project_contents WHERE project_id=? AND is_public=1 ORDER BY sort_order,id');$contents->execute([$p['id']]);$contents=$contents->fetchAll();$faqs=db()->prepare('SELECT question,answer FROM project_faqs WHERE project_id=? AND is_public=1 ORDER BY sort_order');$faqs->execute([$p['id']]);$faqs=$faqs->fetchAll();$related=db()->prepare("SELECT p.id,p.title,p.slug,CASE WHEN p.cover_image_public=1 AND p.cover_image_approved=1 THEN p.cover_image ELSE NULL END AS public_cover_image FROM related_projects r JOIN projects p ON p.id=r.related_project_id WHERE r.project_id=? AND p.status='published' ORDER BY r.sort_order");$related->execute([$p['id']]);$related=$related->fetchAll();$viewCount=db()->prepare('SELECT COUNT(*) FROM page_views WHERE project_id=?');$viewCount->execute([$p['id']]);$views=(int)$viewCount->fetchColumn();$title=$p['seo_title']?:$p['title'];$description=$p['meta_description']?:$p['short_description'];
$schema=['@context'=>'https://schema.org','@type'=>$p['schema_type']==='Article'?'Article':'WebPage','name'=>$p['title'],'description'=>$description,'url'=>$p['canonical_url']?:'https://dreambrixs.com/projects/'.$p['slug']];if($p['public_cover_image'])$schema['image']=base_url('media.php?project='.$p['id'].'&type=cover');
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=e($title)?></title><meta name="description" content="<?=e($description)?>"><meta name="robots" content="<?=!empty($p['robots_index'])?'index,follow':'noindex,nofollow'?>"><link rel="canonical" href="<?=e($p['canonical_url'] ?: 'https://dreambrixs.com/projects/'.$p['slug'])?>"><meta property="og:title" content="<?=e($p['og_title']?:$title)?>"><meta property="og:description" content="<?=e($p['og_description']?:$description)?>"><?php if($p['og_image']):?><meta property="og:image" content="<?=e($p['og_image'])?>"><?php elseif($p['public_cover_image']):?><meta property="og:image" content="<?=e(base_url('media.php?project='.$p['id'].'&type=cover'))?>"><?php endif;?><script type="application/ld+json"><?=json_encode($schema,JSON_UNESCAPED_SLASHES|JSON_UNESCAPED_UNICODE)?></script></head><body><?php if($preview):?><p>ADMIN PREVIEW - views are not counted. <a href="<?=base_url('admin/projects/edit.php?id='.$p['id'])?>">Back to editor</a></p><?php endif;?><nav><a href="/projects">All Projects</a></nav><main><header><?php if($p['public_hero_image']):?><img src="<?=base_url('media.php?project='.$p['id'].'&type=hero'.($preview?'&preview=1':''))?>" alt="<?=e($p['title'])?>" width="100%" style="max-height:420px;object-fit:cover"><?php elseif($p['public_cover_image']):?><img src="<?=base_url('media.php?project='.$p['id'].'&type=cover'.($preview?'&preview=1':''))?>" alt="<?=e($p['title'])?>" width="100%" style="max-height:420px;object-fit:cover"><?php endif;?><h1><?=e($p['h1_heading']?:$p['title'])?></h1><p><?=e($p['short_description'])?></p><p><?=e($p['location']?:$p['city']?:'')?> · <?=e($p['category_name'])?></p><p>Project views: <?=$views?></p></header><?php foreach($contents as $c):?><section><h2><?=e($c['heading'])?></h2><div><?=nl2br(e($c['body']))?></div></section><?php endforeach;?><?php if($specs):?><section><h2>Project Specifications</h2><dl><?php foreach($specs as $s):$val=json_decode($s['value_json'],true);if($s['input_type']==='boolean')$val=$val?'Yes':'No';if(is_array($val))$val=implode(', ',$val);?><dt><?=e($s['label'])?></dt><dd><?=e((string)$val)?> <?=e($s['unit']??'')?></dd><?php endforeach;?></dl></section><?php endif;?><?php if($images):?><section><h2>Project Gallery</h2><?php foreach($images as $im):?><figure><img src="<?=base_url('media.php?image='.$im['id'])?>" alt="<?=e($im['alt_text']?:$p['title'])?>" width="320"><figcaption><?=e($im['caption']??'')?></figcaption></figure><?php endforeach;?></section><?php endif;?><?php if($faqs):?><section><h2>Frequently Asked Questions</h2><?php foreach($faqs as $f):?><h3><?=e($f['question'])?></h3><p><?=e($f['answer'])?></p><?php endforeach;?></section><?php endif;?><?php if($related):?><section><h2>Related Projects</h2><?php foreach($related as $r):?><article><a href="/projects/<?=e($r['slug'])?>"><?php if($r['public_cover_image']):?><img src="<?=base_url('media.php?project='.$r['id'].'&type=cover')?>" width="160" alt="<?=e($r['title'])?>"><?php endif;?><?=e($r['title'])?></a></article><?php endforeach;?></section><?php endif;?></main></body></html>
